package com.example.rokidgeminisecretary;import android.content.*;import org.json.*;import java.io.*;import java.nio.file.*;class ConversationWorkspace {static JSONObject read(Context c,String name)throws Exception{File f=new File(c.getFilesDir(),name+".gcm");if(!f.isFile())throw new FileNotFoundException();return new JSONObject(new String(DeviceSecrets.photos().decrypt(Files.readAllBytes(f.toPath())),"UTF-8"));}static void write(Context c,String name,JSONObject value)throws Exception{Files.write(new File(c.getFilesDir(),name+".gcm").toPath(),DeviceSecrets.photos().encrypt(value.toString().getBytes("UTF-8")));}}